#[test]
fn custom_fragment_keys_match_pr148_rails() {
    use campfire_views::fragment_cache::keys::{self, MessageKey};
    let vectors: Value = serde_json::from_str(&fixture("cache_keys.json")).unwrap();
    let timestamp = |value: &Value| {
        value
            .as_str()
            .map(|value| value.parse::<jiff::Timestamp>().unwrap())
    };
    let stamps = |value: &Value| {
        value
            .as_array()
            .map(|values| values.iter().filter_map(timestamp).collect::<Vec<_>>())
            .unwrap_or_default()
    };
    assert_eq!(
        keys::PRESENTATION_CACHE_VERSION,
        vectors["presentation_cache_version"].as_i64().unwrap()
    );
    for row in vectors["quote_names_digests"].as_array().unwrap() {
        let names: Vec<(String, String)> = row[0]
            .as_array()
            .unwrap()
            .iter()
            .map(|pair| {
                (
                    pair[0].as_str().unwrap().into(),
                    pair[1].as_str().unwrap().into(),
                )
            })
            .collect();
        assert_eq!(keys::quote_names_inspect(&names), row[2].as_str().unwrap());
        assert_eq!(keys::quote_names_digest(&names), row[1].as_str().unwrap());
    }
    for row in vectors["message_with_pr_cards"].as_array().unwrap() {
        let data = MessageKey {
            record: row["message"].as_str().unwrap().into(),
            cards: stamps(&row["cards"]),
            embeds: row["embeds"]
                .as_array()
                .map(|embeds| {
                    embeds
                        .iter()
                        .map(|pair| (pair[0].as_i64().unwrap(), timestamp(&pair[1])))
                        .collect()
                })
                .unwrap_or_default(),
            has_pull_requests: row["has_pull_requests"].as_bool().unwrap_or(false),
            pr_threads_stamp: timestamp(&row["pr_threads_stamp"]),
            pins: stamps(&row["pins"]),
            thread_messages_count: row["thread_messages_count"].as_i64(),
            poll: timestamp(&row["poll"]),
            system_note: row["system_note"].as_bool().unwrap_or(false),
            streaming: row["streaming"].as_bool().unwrap_or(false),
            agent_steps: stamps(&row["agent_steps"]),
            quotes: row["quoted_sources"]
                .as_array()
                .map(|sources| {
                    sources
                        .iter()
                        .map(|source| {
                            (
                                timestamp(&source["edited_at"])
                                    .max(timestamp(&source["updated_at"]))
                                    .unwrap(),
                                source["creator"].as_str().unwrap().into(),
                                source["room"].as_str().map(str::to_owned),
                            )
                        })
                        .collect()
                })
                .unwrap_or_default(),
        };
        for zone in ["UTC", "Hawaii"] {
            let zone_model = campfire_views::time::Zone::lookup(zone).unwrap();
            let key = keys::message_with_pr_cards(&data);
            assert_eq!(
                keys::expand(&key, &zone_model),
                row["expanded"][zone]["key"].as_str().unwrap(),
                "{}, {zone}",
                row["label"]
            );
            assert_eq!(
                keys::fragment("messages/_message", "0123abcd", &key, &zone_model),
                row["expanded"][zone]["fragment"].as_str().unwrap()
            );
        }
    }
    for row in vectors["sidebar_membership"].as_array().unwrap() {
        let participants: Option<Vec<i64>> = row["participant_ids"]
            .as_array()
            .map(|values| values.iter().map(|value| value.as_i64().unwrap()).collect());
        let key = keys::sidebar_membership(
            row["membership"].as_str().unwrap(),
            participants.as_deref(),
            row["administrator"].as_bool().unwrap(),
        );
        assert_eq!(
            keys::expand(&key, &campfire_views::time::Zone::utc()),
            row["key"].as_str().unwrap()
        );
    }
}

#[test]
fn shared_avatar_links_and_first_paint_preloads_match_rails() {
    let asset = |path: &str| campfire_assets::asset_path(path);
    let signer = |_: &[&str]| String::new();
    let ctx = context(None, &asset, &signer, "");
    let helpers: Value = serde_json::from_str(&fixture("helpers.json")).unwrap();
    for row in helpers["avatars"].as_array().unwrap() {
        let facts = facts();
        let user = &facts["users"][row["user"].as_str().unwrap()];
        let user = h::AvatarUser {
            id: user["id"].as_i64().unwrap(),
            title: row["title"].as_str().unwrap().into(),
            avatar_path: user["avatar_path"].as_str().unwrap().into(),
        };
        assert!(compare(
            "avatar",
            &h::avatar_tag(&ctx, &user, h::attrs().size(32).loading("lazy")).0,
            row["html"].as_str().unwrap()
        ));
    }
    let actual = h::request_forgery::rendering_with(
        h::request_forgery::RequestSecrets {
            tokens: Box::new(Tokens),
            csp_nonce: Some("NONCE".into()),
        },
        || h::first_paint_controller_preloads(&ctx).0,
    );
    assert!(compare(
        "first_paint_controller_preloads",
        &actual,
        &fixture("partials/first_paint_controller_preloads.html")
    ));
}

#[test]
fn byte_comparison_rejects_markup_whitespace_and_asset_changes() {
    let expected = fixture("layouts/application_signed_out.html");
    for (name, changed) in [
        (
            "injected_title",
            expected.replacen("Smartfire</title>", "Wrong</title>", 1),
        ),
        ("injected_space", format!("{expected} ")),
        (
            "injected_asset",
            expected.replacen("/assets/", "/wrong-assets/", 1),
        ),
    ] {
        assert_ne!(changed, expected, "injection must modify the fixture");
        assert!(!compare(name, &changed, &expected));
    }
}

#[test]
fn live_application_layout_rejects_dropped_reordered_stylesheets_and_wrong_digests() {
    let asset = |path: &str| campfire_assets::asset_path(path);
    let signer = |_: &[&str]| String::new();
    let styles = campfire_assets::stylesheet_link_tag_all(&[("data-turbo-track", "reload")]).html;
    let ctx = context(None, &asset, &signer, &styles);
    let page = layouts::Application::new(&ctx, h::raw("<p>Body</p>\n"));
    let actual = render(&page);
    assert!(compare("live layout", &actual, &actual));
    let tags: Vec<_> = styles.split_inclusive('>').take(2).collect();
    let people = campfire_assets::stylesheet_path("people");
    for (mutation, changed) in [
        ("drop stylesheet", actual.replacen(tags[0], "", 1)),
        (
            "reorder stylesheets",
            actual.replacen(
                &format!("{}{}", tags[0], tags[1]),
                &format!("{}{}", tags[1], tags[0]),
                1,
            ),
        ),
        (
            "wrong digest",
            actual.replacen(&people, "/assets/people-00000000.css", 1),
        ),
    ] {
        assert_ne!(changed, actual, "{mutation} must change the rendered page");
        assert!(!compare(mutation, &changed, &actual));
    }
}
